corpus_block("test-guide-legend.R: show.legend handles named vectors", {
  skip_on_cran()
  n_legends <- function(p) {
      g <- ggplotGrob(p)
      gb <- grep("guide-box", g$layout$name)
      n <- vapply(g$grobs[gb], function(x) {
        if (is_zero(x)) return(0)
        length(x$grobs) - 1
      }, numeric(1))
      sum(n)
    }
  df <- data_frame(x = 1:3, y = 20:22)
  .plot("test-guide-legend.R: show.legend handles named vectors #1", p <- ggplot(df, aes(x = x, y = y, color = x, shape = factor(y))) +
      geom_point(size = 20))
  .plot("test-guide-legend.R: show.legend handles named vectors #2", p <- ggplot(df, aes(x = x, y = y, color = x, shape = factor(y))) +
      geom_point(size = 20, show.legend = c(color = FALSE)))
  .plot("test-guide-legend.R: show.legend handles named vectors #3", p <- ggplot(df, aes(x = x, y = y, color = x, shape = factor(y))) +
      geom_point(size = 20, show.legend = c(color = FALSE, shape = FALSE)))
  .plot("test-guide-legend.R: show.legend handles named vectors #4", p <- ggplot(df, aes(x = x, y = y, color = x, shape = factor(y))) +
      geom_point(size = 20, show.legend = c(shape = FALSE, color = TRUE)))
})

