corpus_block("test-guide-legend.R: legends can be forced to display unrelated geoms", {
  skip_on_cran()
  df <- data.frame(x = 1:2)
  .plot("test-guide-legend.R: legends can be forced to display unrelated geoms #1", p <- ggplot(df, aes(x, x)) +
      geom_tile(fill = "red", show.legend = TRUE) +
      scale_colour_discrete(
        limits = c("A", "B")
      ))
  b <- ggplot_build(p)
  legend <- b@plot@guides$params[[1]]
})

